BEGIN READ ONLY; SELECT jsonb_build_object('observed_at',now(),'catalog',(SELECT jsonb_agg(t) FROM (SELECT calculator_key,slug,version,lifecycle,risk_class,source_count,metadata->'certification' AS certification,metadata->'canonical' AS canonical FROM public.calculator_catalog_admin ORDER BY calculator_key,version)t),'qa_counts',(SELECT jsonb_agg(t) FROM (SELECT check_type,status,count(*) AS count FROM public.calculator_qa_checks GROUP BY check_type,status ORDER BY check_type,status)t)) AS evidence; ROLLBACK;
